export function formatOtherTime(at: Date, tz: string, viewerTz: string): string {
  const time = `${formatTime(at, tz)} ${zoneAbbreviation(at, tz)}`;
  return localDate(at, tz) === localDate(at, viewerTz) ? time : `${formatDate(at, tz)}, ${time}`;
}
